export function translateText(value, language) {
  if (!language || language === 'en') return value;
  const dict = ptExtra[language] || {};
  if (dict[value]) return dict[value];
  if (value === 'Kriptal home') return translateAttribute(value, language);
  if (value.startsWith('Verified from ')) return `${translateText('Verified from', language)} ${value.slice('Verified from '.length)}`;
  if (value.startsWith('Download ')) return `${translateText('Download file', language)} ${value.slice('Download '.length)}`;
  if (value.includes(' · ') && value.includes('added')) {
    const [username, fingerprint] = value.split(' · ');
    return `${username} ${translateText('added', language)} · ${fingerprint}`;
  }
  return value;
}

export function languageTag(language) {
  return languages.find((item) => item.code === language)?.tag || 'en';
}

export function translateAttribute(value, language) {
  const attrMap = {
    'Kriptal home': { es:'Inicio de Kriptal',it:'Home di Kriptal',pt:'Início do Kriptal',nl:'Kriptal-home',fr:'Accueil Kriptal',zh:'Kriptal 首页',ja:'Kriptal ホーム',ru:'Главная Kriptal',eo:'Hejmo de Kriptal' },
    'e.g. maren': { es:'p. ej., maren',it:'es. maren',pt:'ex.: maren',nl:'bijv. maren',fr:'ex. : maren',zh:'例如：maren',ja:'例：maren',ru:'например, maren',eo:'ekz. maren' },
    'Write something only your contact can read...': { es:'Escribe algo que solo tu contacto pueda leer...',it:'Scrivi qualcosa che solo il contatto possa leggere...',pt:'Escreva algo que só seu contato possa ler...',nl:'Schrijf iets dat alleen je contact kan lezen...',fr:'Écrivez quelque chose que seul votre contact peut lire...',zh:'写下只有联系人能读到的内容...',ja:'連絡先だけが読める内容を入力...',ru:'Напишите то, что сможет прочитать только ваш контакт...',eo:'Skribu ion legeblan nur de via kontakto...' }
  };
  return attrMap[value]?.[language] || translateText(value, language);
}
